```openscad
// Flask support ring with three round legs
// Print orientation: ring top face at z = 60, legs run down to z = 0

// ---------- Parameters ----------
ring_outer_d      = 90;    // ring outer diameter
ring_inner_d      = 66;    // ring inner (bore) diameter
ring_thickness    = 6;     // ring thickness (Z)
ring_top_z        = 60;    // ring top face height
leg_d             = 6;     // leg diameter
leg_count         = 3;     // number of legs
leg_circle_d      = 78;    // diameter of circle the leg axes lie on
leg_angle         = 120;   // angle between legs (degrees)
leg_first_on_x    = true;  // first leg on +X axis
cut_overlap       = 0.5;   // extra length of cutters past faces
$fn               = 96;    // curve resolution

// ---------- Derived ----------
leg_bottom_z = 0;                        // legs end at the bed
ring_bottom_z = ring_top_z - ring_thickness;  // ring bottom face (54)
leg_cylinder_h = ring_bottom_z + cut_overlap;  // legs extend through ring + overlap

// ---------- Model ----------
union() {
    // Flat annulus ring
    difference() {
        cylinder(d = ring_outer_d, h = ring_thickness, $fn = 128);
        translate([0, 0, ring_bottom_z])
            cylinder(d = ring_inner_d, h = ring_thickness + 1, $fn = 128);
    }

    // Three support legs
    for (i = [0 : leg_count - 1]) {
        a = leg_angle * i;
        translate([leg_circle_d / 2 * cos(a),
                   leg_circle_d / 2 * sin(a),
                   leg_bottom_z])
            cylinder(d = leg_d, h = leg_cylinder_h, $fn = 64);
    }
}
```

```openscad
// Round-bottom flask support ring on three legs
// Print orientation: legs on bed at z = 0, ring at top

$fn = 96;

// ---- Ring ----
ring_od      = 90;   // ring outer diameter
ring_id      = 66;   // ring inner diameter
ring_t       = 6;    // ring thickness
ring_top_z   = 60;   // z of ring top face

// ---- Legs ----
leg_d        = 6;    // leg diameter
leg_circle_d = 78;   // diameter of circle through leg axes
leg_count    = 3;    // number of legs
leg_start_a  = 0;    // angle of first leg (on +X axis)
leg_overlap  = 0.5;  // how far legs extend into ring for a solid union

// ---- Derived ----
ring_bot_z   = ring_top_z - ring_t;
eps          = 0.5;  // cutter overrun past faces

union() {
    // Flat annular ring
    translate([0, 0, ring_bot_z])
        difference() {
            cylinder(d = ring_od, h = ring_t);
            translate([0, 0, -eps])
                cylinder(d = ring_id, h = ring_t + 2 * eps);
        }

    // Legs, straight down from the ring to the bed
    for (i = [0 : leg_count - 1]) {
        a = leg_start_a + i * 360 / leg_count;
        translate([leg_circle_d / 2 * cos(a), leg_circle_d / 2 * sin(a), 0])
            cylinder(d = leg_d, h = ring_bot_z + leg_overlap);
    }
}
```

