```openscad
// Round-bottom flask support ring on three legs
// Units: mm. Print orientation: legs stand on the bed (z = 0), ring on top.

$fn = 96;

// ---- Ring ----
ring_od        = 70;    // ring outer diameter
ring_id        = 54;    // ring inner diameter
ring_thick     = 6;     // ring thickness (Z)
ring_top_z     = 50;    // height of ring top face
ring_bottom_z  = ring_top_z - ring_thick;   // = 44

// ---- Legs ----
leg_d          = 8;     // leg diameter
leg_pcd        = 62;    // diameter of circle through leg axes
leg_count      = 3;     // number of legs
leg_start_ang  = 0;     // first leg on +X axis
leg_overlap    = 0.5;   // legs extend into ring for a solid union

eps            = 0.5;   // cutter overshoot

// Ring (annulus)
module ring() {
    translate([0, 0, ring_bottom_z])
        difference() {
            cylinder(d = ring_od, h = ring_thick);
            translate([0, 0, -eps])
                cylinder(d = ring_id, h = ring_thick + 2 * eps);
        }
}

// Legs
module legs() {
    for (i = [0 : leg_count - 1]) {
        a = leg_start_ang + i * 360 / leg_count;
        translate([leg_pcd / 2 * cos(a), leg_pcd / 2 * sin(a), 0])
            cylinder(d = leg_d, h = ring_bottom_z + leg_overlap);
    }
}

union() {
    ring();
    legs();
}
```

