// Sliding mount with dovetail rail
// Print orientation: base plate on bed (z = 0), rail builds upward (+Z)

// ---------- Parameters ----------
plate_len      = 120;   // base plate length (X)
plate_wid      = 36;    // base plate width (Y)
plate_thk      = 5;     // base plate thickness (Z)

rail_bot_w     = 12;    // rail width at bottom face (z = 5), where it meets plate
rail_top_w     = 16;    // rail width at top face (z = 11)
rail_h         = 6;     // rail height (top z - bottom z) = 11 - 5

overcut        = 0.5;   // extra length rail extends past plate ends for clean union
$fn            = 96;    // curve resolution (no curves here, set per the rules)

// ---------- Derived ----------
rail_top_z     = plate_thk + rail_h;   // top of rail (5 + 6 = 11)
slope          = (rail_top_w - rail_bot_w) / (2 * rail_h);  // flare per mm height (4/12 = 0.33)

// ---------- Model ----------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail, centred on y = 0, running full length
    translate([-plate_len/2 - overcut, 0, plate_thk])
        linear_extrude(height = rail_h + overcut)
            polygon([[-rail_bot_w/2, 0], [rail_bot_w/2, 0],
                     [rail_top_w/2, rail_h], [-rail_top_w/2, rail_h]]);
}
