```openscad
// Glass stirring rod rest
// Print orientation: base on bed (z = 0), grooves facing up

// ---------- Parameters ----------
block_len   = 84;    // block length along X (mm)
block_wid   = 50;    // block width along Y (mm)
block_ht    = 12;    // block height along Z (mm)

groove_n     = 4;    // number of V-grooves
groove_pitch = 18;   // centre-to-centre spacing along X (mm)
groove_w     = 8;    // groove width at top surface (mm)
groove_d     = 4;    // groove depth from top surface (mm)

eps          = 0.5;  // overcut past faces to avoid coplanar faces (mm)

$fn = 96;

// ---------- Derived ----------
// For a 90-degree V, the side walls are at 45 degrees.
// Extending the V above the top surface by eps makes the opening
// 2*eps wider there, so the V axis passes exactly through the top corners.
overcut_w = groove_w + 2 * eps;              // opening width at z = block_ht + eps
axis_x    = -groove_pitch * (groove_n + 1) / 2; // first groove centre (pattern centred)

// ---------- Model ----------
difference() {
    // Main block
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves cut full width along Y
    for (i = [0 : groove_n - 1]) {
        translate([axis_x + i * groove_pitch, -block_wid / 2 - eps, block_ht])
            linear_extrude(height = block_wid + 2 * eps)
                polygon([[-groove_w / 2, 0], [groove_w / 2, 0],
                         [0, -overcut_w / 2], [0, overcut_w / 2]]);
    }
}
