// ---------------- Derived ----------------
// For a 90-degree V, the two faces are at 45 degrees.
// The width narrows by 2*depth as it goes down, so the opening at depth d
// is groove_wt - 2*d. That is the length of the line the cutter follows.
V_len = groove_wt - 2 * groove_d;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves running the full width along Y, centred along X
    for (i = [0 : groove_n - 1]) {
        x_c = (i - (groove_n - 1)/2) * groove_pitch;
        translate([x_c - block_len/2, -block_wid/2, block_ht - groove_d])
            linear_extrude(height = V_len)
                polygon([[-1, 0], [1, 0], [0, -1]]);   // 90-degree V in XZ
    }
