    for (x = groove_x)
        translate([x - groove_wt / 2, -block_wid / 2 - eps, groove_ext])
            rotate([0, 90, 0])
                linear_extrude(height = block_wid + 2 * eps)
                    polygon([[-groove_wt / 2, 0], [groove_wt / 2, 0],
                              [0, -groove_ext]]);
