// Split collet - a round tube with axial slots that opens at the top to grip a tube
// Print orientation: standing on the bed, slots facing up (+Z)
//

// ---- Parameters (mm) ----
collet_od      = 16;   // outer diameter of collet
collet_bore    = 10;   // bore diameter (through the full length)
collet_height  = 20;   // total height of collet (z = 0 to z = 20)
slot_width     = 2;    // width of each axial slot
slot_depth     = 10;   // slots run from the top end down to z = 10
slot_count     = 4;    // number of slots, evenly spaced
first_slot_az  = 0;    // azimuth of first slot (0 = +X axis)

// ---- Modelling helpers ----
eps   = 0.5;          // overshoot for clean boolean cuts
$fn   = 96;           // curve resolution

// ---- Model ----
difference() {
    // Main tube body
    cylinder(d = collet_od, h = collet_height);

    // Central bore
    translate([0, 0, -eps])
        cylinder(d = collet_bore, h = collet_height + 2 * eps);

    // Axial slots, cut from the top end down to z = slot_depth
    for (i = [0 : slot_count - 1]) {
        a = first_slot_az + i * 360 / slot_count;
        translate([0, 0, collet_height - slot_depth])
            translate([0, 0, eps])
                cylinder(d = slot_width, h = slot_depth + eps,
                         $fn = 16,
                         rotate = [0, 0, a]);
    }
}
