// Stepped riser - solid staircase of 3 equal steps, print orientation: base on bed,
// climbing in +X. NOVEL general part.
//

step_x   = 12;   // step length along X
step_h   = 6;    // step height increase
top_h    = 18;   // top step height (3 * step_h)
length_y = 40;   // extrusion length along Y
eps      = 0.5;  // cutter overshoot

$fn = 64;

difference() {
    union() {
        for (i = [0 : 2])
            translate([i * step_x, 0, i * step_h])
                cube([step_x, length_y, step_h]);
    }
    // cut a flat on the top face so the last cutter face is not coplanar with the solid
    translate([2 * step_x, 0, top_h])
        cube([step_x, length_y, eps]);
}
