```openscad
// Stepped riser - solid 3-step staircase climbing in +X
// Print orientation: resting on bed at z = 0, building upward (+Z)
// Positioned per user coordinates: x = 0..36, y = 0..40 (not centred)

// ---------------- Parameters ----------------
n_steps     = 3;    // number of steps
step_len    = 12;   // length of each step along X (mm)
step_rise   = 6;    // height increase per step (mm); first step height = 6
riser_width = 40;   // extrusion length along Y (mm)

total_len    = n_steps * step_len;   // 36 mm overall length in X
total_height = n_steps * step_rise;  // 18 mm top step height

// ---------------- Profile (XZ plane) ----------------
// Staircase outline: starts at origin, climbs step by step, then drops
// straight down to the bed at x = total_len. Solid down to z = 0.
profile_pts = concat(
    [[0, 0]],
    [for (i = [0 : n_steps - 1]) each [
        [i * step_len,       (i + 1) * step_rise],   // top-left corner of step i
        [(i + 1) * step_len, (i + 1) * step_rise]    // top-right corner of step i
    ]],
    [[total_len, 0]]
);

// ---------------- Model ----------------
// Polygon drawn in XY (Y = height), extruded along Z, then rotated so
// height becomes +Z and the extrusion runs along Y from 0 to riser_width.
translate([0, riser_width, 0])
    rotate([90, 0, 0])
        linear_extrude(height = riser_width)
            polygon(points = profile_pts);
```

```openscad
// Stepped riser - solid staircase of 3 equal steps, print orientation: base on bed,
// profile climbs in +X direction. NOVEL general part.
//

$fn = 64;

// ---- Dimensions (mm) ----
step_count   = 3;     // number of steps
step_length  = 12;    // X length of each step
step_height  = 6;     // height gain of each step over the previous
top_height   = 18;    // height of the top step (3 * step_height)
extrusion    = 40;    // Y length of the part (y = 0 to 40)
overcut      = 0.5;   // extra length so cutters pass beyond the end faces

// Derived
x0 = 0;                       // X start of first step
x_end = x0 + step_count * step_length; // X end of last step (36)

difference() {
    // Main body: union of the steps, each solid down to the bed (z = 0)
    union() {
        for (i = [0 : step_count - 1]) {
            translate([x0 + i * step_length, 0, i * step_height])
                cube([step_length, extrusion, step_height]);
        }
    }

    // Clean up end faces: cutters run along Y, extend past both ends
    translate([x_end - step_length / 2, -overcut, 0])
        cube([step_length / 2 + overcut, extrusion + 2 * overcut, top_height]);

    translate([x0 + step_length / 2, -overcut, 0])
        cube([step_length / 2 + overcut, extrusion + 2 * overcut, top_height]);
}
