// Display base with bevelled top edges
// Print orientation: flat on bed, bevelled face up

// ---- Dimensions (mm) ----
block_x      = 80;    // block length (X)
block_y      = 40;    // block width (Y)
block_h      = 15;    // block height (Z)
chamfer_w    = 2;     // chamfer width (45 deg -> cuts 2 mm into X and Y)
chamfer_stop = block_h - 2; // vertical sides stop here (z = 13)
eps          = 0.5;   // overcut past faces

$fn = 64;

difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // Top face, reduced by the chamfers (76 x 36)
    translate([-block_x/2 - eps, -block_y/2 - eps, chamfer_stop])
        cube([block_x + 2*eps, block_y + 2*eps, eps]);

    // Four vertical sides, cut back by the 45-degree chamfers
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx > 0 ? block_x/2 - chamfer_w : -block_x/2,
                   sy > 0 ? block_y/2 - chamfer_w : -block_y/2,
                   0])
