plate_wid      = 30;    // base plate width (Y)
plate_thk      = 6;     // base plate thickness (Z)

rail_bot_w     = 8;     // rail width at bottom face (z = plate_thk)
rail_top_w     = 14;    // rail width at top face (z = plate_thk + rail_h)
rail_h         = 8;     // rail height (top face at z = 14)

eps            = 0.5;   // overcut for clean boolean differences
$fn            = 96;    // curve resolution

// ---------- Derived ----------
rail_x0 = -(rail_bot_w + rail_top_w) / 2;   // lower corner X (left)
rail_x1 = (rail_bot_w + rail_top_w) / 2;    // upper corner X (right)
slope  = (rail_top_w - rail_bot_w) / rail_h;   // flare per mm height

// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail (flares outward as it rises)
    translate([-plate_len/2, 0, plate_thk])
        linear_extrude(height = rail_h + eps)
            polygon([
                [rail_x0, -rail_bot_w/2],
                [rail_x0, rail_bot_w/2],
                [rail_x1, rail_top_w/2],
                [rail_x1, -rail_top_w/2]
            ]);
}
