```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate on bed (z = 0), rail builds upward (+Z)

// ---------------- Parameters ----------------
plate_len   = 120;   // base plate length (X)
plate_wid   = 30;    // base plate width (Y)
plate_thk   = 6;     // base plate thickness (Z)

rail_bot_w  = 8;     // dovetail rail width at plate top (z = 6)
rail_top_w  = 14;    // dovetail rail width at top face (z = 14)
rail_h      = 8;     // dovetail rail height (z = 6 to z = 14)

eps         = 0.5;   // cutter overshoot past faces
$fn         = 96;    // curve resolution

// Derived: rail slope (Y per unit Z), used to extend cutters along Z
rail_slope  = (rail_top_w - rail_bot_w) / (2 * rail_h);

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail, centred on y = 0, running full length along X
    translate([-plate_len/2, 0, plate_thk])
        linear_extrude(height = plate_len)
            polygon([[-rail_bot_w/2, 0], [rail_bot_w/2, 0],
                     [rail_top_w/2, rail_h], [-rail_top_w/2, rail_h]]);
}

// ---------------- Inspect ----------------
difference() {
    // Duplicate of the model, with a cut through the rail near its top
    translate([-plate_len/2, 0, plate_thk])
        linear_extrude(height = plate_len)
            polygon([[-rail_bot_w/2, 0], [rail_bot_w/2, 0],
                     [rail_top_w/2, rail_h], [-rail_top_w/2, rail_h]]);

    // Cutter: prism along X, rectangular in YZ, centred on the rail
    translate([-plate_len/2 - eps, 0,
               plate_thk + rail_h - eps * rail_slope])
        cube([plate_len + 2*eps, rail_top_w + 2*eps, eps]);
}
