// Dovetail rail mount - a base plate with a flaring dovetail rail on top
// Print orientation: base plate on the bed (z = 0), rail builds upward (+Z)

// ---------------- Parameters ----------------
plate_len    = 100;   // base plate length along X (mm)
plate_wid    = 36;    // base plate width along Y (mm)
plate_thk    = 5;     // base plate thickness along Z (mm)

rail_bot_w   = 10;    // dovetail rail width at the plate top (z = 5) (mm)
rail_top_w   = 16;    // dovetail rail width at its top face (z = 13) (mm)
rail_top_z   = 13;    // dovetail rail top face height above the bed (mm)

eps          = 0.5;   // overcut so cutting shapes pass beyond faces (mm)
$fn          = 96;    // curve resolution

// ---------------- Derived ----------------
rail_h       = rail_top_z - plate_thk;              // rail height above plate (8 mm)
flare        = (rail_top_w - rail_bot_w) / rail_h;  // outward flare per mm of height
x0_bot       = -rail_bot_w / 2;                     // rail outer X at z = 5
x0_top       = -rail_top_w / 2;                     // rail outer X at z = 13

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail: centred on y = 0, running the full length along X
    translate([-plate_len / 2, -plate_wid / 2, plate_thk])
        linear_extrude(height = plate_len)
            hull() {
                for (z = [0 : rail_h]) {
                    w = rail_bot_w + flare * z;
                    translate([x0_bot + flare * z / 2, 0])
                        cube([w, plate_wid + eps, 1]);   // 1 mm thick slice, overcut in Y
                }
            }
}
