plate_len   = 60;   // plate length along X
plate_wid   = 30;   // plate width along Y
plate_thk   = 6;    // plate thickness along Z (z = 0..6)

// ---------------- Dovetail rail ----------------
rail_len    = plate_len; // rail runs the full plate length
rail_w_base = 12;   // rail width where it meets the plate (z = 6)
rail_w_top  = 16;   // rail width at its top face (z = 11)
rail_top_z  = 11;   // absolute Z of rail top face
rail_h      = rail_top_z - plate_thk; // rail height (5 mm)

// ---------------- Misc ----------------
overlap     = 0.01; // small overlap so rail fuses into plate (no coplanar faces)

module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

// Trapezoid profile in (Y, Z), extruded along X
module dovetail_rail() {
    translate([-rail_len/2, 0, 0])
        rotate([90, 0, 90])          // 2D (x,y) -> world (Y,Z), extrusion -> +X
            linear_extrude(height = rail_len)
                polygon(points = [
                    [-rail_w_base/2, plate_thk - overlap],
                    [ rail_w_base/2, plate_thk - overlap],
                    [ rail_w_top/2,  rail_top_z],
                    [-rail_w_top/2,  rail_top_z]
                ]);
}

union() {
    base_plate();
    dovetail_rail();
}
