hole_floor  = 2;     // hole bottom height above bed (closed floor)
eps         = 0.5;   // overshoot for clean boolean cuts

$fn = 128;           // resolution for curved surfaces

// ---- Model ----
difference() {
    union() {
        // Base disc
        cylinder(d = disc_d, h = disc_h);
        // Boss (overlaps disc slightly so the union is one solid)
        translate([0, 0, disc_h - eps])
            cylinder(d = boss_d, h = boss_top_z - disc_h + eps);
    }
    // Rod hole: from 2 mm above the bed up through the top of the boss
    translate([0, 0, hole_floor])
        cylinder(d = hole_d, h = boss_top_z - hole_floor + eps);
}
