// Glass stirring rod rest - block with V-shaped grooves along Y
// Print orientation: flat on bed, grooves facing up

// ---- Block dimensions ----
block_len   = 120;   // length along X (mm)
block_wid   = 30;    // width along Y (mm)
block_ht    = 18;    // height along Z (mm)

// ---- Groove parameters ----
groove_n     = 6;    // number of V-grooves
groove_pitch = 20;   // centre-to-centre spacing along X (mm)
groove_wt    = 10;   // groove width at top surface (mm)
groove_depth = 5;    // groove depth from top surface (mm)

// ---- Derived ----
overcut = 0.5;       // extra length so cutters pass through faces
$fn = 96;            // curve resolution

// V-groove 90-degree: each side slopes 45 deg, so side length = width / sqrt(2)
function vlen(w) = w / sqrt(2);

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves running full width along Y
    for (i = [0 : groove_n - 1]) {
        x = (i - (groove_n - 1) / 2) * groove_pitch;
        translate([x - block_len/2, 0, block_ht - groove_depth])
            linear_extrude(vlen(groove_wt))
                translate([0, 0, -overcut])
                    union() {
                        translate([-vlen(groove_wt)/2, -block_wid/2 - overcut, 0])
                            cube([vlen(groove_wt), block_wid + 2*overcut, groove_depth + overcut]);
                        translate([vlen(groove_wt)/2, -block_wid/2 - overcut, 0])
                            cube([vlen(groove_wt), block_wid + 2*overcut, groove_depth + overcut]);
                    }
    }
}
