// Glass stirring rod rest - rectangular block with V-grooves across the top
// Print orientation: base flat on bed (z = 0), grooves facing up

// ---------------- Parameters ----------------
block_len    = 114;   // block length along X (mm)
block_wid    = 50;    // block width along Y (mm)
block_h      = 15;    // block height along Z (mm)

groove_count = 6;     // number of V-grooves
groove_pitch = 18;    // centre-to-centre groove spacing along X (mm)
groove_top_w = 10;    // groove width at the top surface (mm)
groove_depth = 5;     // groove depth from top surface (mm), 90-degree V

overshoot    = 0.5;   // extra cutter extension past cut faces (mm)

$fn = 64;

// ---------------- Derived ----------------
half_w = groove_top_w / 2;              // half-width at top (equals depth for 90 deg)
first_x = -(groove_count - 1) * groove_pitch / 2;  // centre the groove set on X

// ---------------- Modules ----------------
// V-groove cutter: 90-degree V profile in XZ, extruded through the full Y width.
// The profile continues above the top face by 'overshoot' keeping the 45-degree flanks.
module v_groove_cutter() {
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * overshoot, center = true)
            polygon(points = [
                [0, block_h - groove_depth],                          // apex
                [ half_w + overshoot, block_h + overshoot],           // top right
                [-(half_w + overshoot), block_h + overshoot]          // top left
            ]);
}

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // Six V-grooves running full width along Y
    for (i = [0 : groove_count - 1])
        translate([first_x + i * groove_pitch, 0, 0])
            v_groove_cutter();
}
