    cylinder(d = collet_od, h = collet_height);

    // Central bore
    translate([0, 0, -1])
        cylinder(d = collet_bore, h = collet_height + 2);

    // Axial slots, first centred on +X
    for (i = [0 : slot_count - 1]) {
        rotate([0, 0, i * 360 / slot_count])
            translate([0, 0, slot_start_z])
                cylinder(d = slot_width, h = slot_depth + overcut);
