// Stepped riser - solid staircase of 4 equal steps
// Profile in XZ climbs in +X; extruded along Y from y = 0 to y = 20.
// Positioned at the coordinates given (x 0..48, y 0..20), resting on z = 0.

// ---------------- Parameters ----------------
n_steps     = 4;    // number of steps
step_len    = 12;   // length of each step along X (mm)
step_rise   = 6;    // height increase per step (mm)
depth_y     = 20;   // extrusion depth along Y (mm)

total_len   = n_steps * step_len;    // 48 mm overall length
total_h     = n_steps * step_rise;   // 24 mm top step height

$fn = 64;           // not strictly needed (no curves), kept per convention

// ---------------- Profile (X, Z) ----------------
// Bottom edge along the bed, then up and over each step, back down at x = 0.
profile_pts = concat(
    [[0, 0], [total_len, 0]],
    // Walk back from the top step to the first: two corners per step
    [ for (i = [n_steps - 1 : -1 : 0]) each [
        [(i + 1) * step_len, (i + 1) * step_rise],  // front-right corner of step tread
        [ i      * step_len, (i + 1) * step_rise]   // back-left corner of step tread
      ] ]
);

// ---------------- Solid ----------------
// rotate([90,0,0]) maps the 2D Y axis to +Z and extrudes toward -Y,
// so shift by depth_y to occupy y = 0 .. 20.
translate([0, depth_y, 0])
    rotate([90, 0, 0])
        linear_extrude(height = depth_y)
            polygon(profile_pts);
