// Stepped riser: solid staircase of 5 equal steps, climbing in +X
// Positioned per user coordinates: x = 0..75, y = 0..30, z = 0 upward

// ---------------- Parameters ----------------
n_steps    = 5;     // number of steps
step_len   = 15;    // length of each step along X (mm)
step_rise  = 6;     // height increment per step (mm)
depth_y    = 30;    // extrusion depth along Y (mm)

total_len  = n_steps * step_len;   // 75 mm overall length in X
top_height = n_steps * step_rise;  // 30 mm top step height

// ---------------- Profile (XZ) ----------------
// Staircase outline: start at origin, run along bed to x = 75,
// up to top height, then step down toward x = 0.
profile_pts = concat(
    [[0, 0], [total_len, 0]],
    [ for (i = [n_steps - 1 : -1 : 0])
        each [
            [(i + 1) * step_len, (i + 1) * step_rise],
            [ i      * step_len, (i + 1) * step_rise]
        ]
    ]
);

// ---------------- Solid ----------------
// Profile drawn in 2D XY, rotated so 2D Y becomes Z,
// extruded along -Y then shifted to occupy y = 0..depth_y.
module stepped_riser() {
    translate([0, depth_y, 0])
        rotate([90, 0, 0])
            linear_extrude(height = depth_y)
                polygon(points = profile_pts);
}

stepped_riser();
