tie_hole  = 5;     // cable-tie hole diameter (mm)
tie_x     = -24;   // cable-tie hole centre X position (mm)
tie_y     = 0;     // cable-tie hole centre Y position (mm)
eps       = 0.5;   // cutter overshoot past faces (mm)

$fn = 64;

// ---------- Derived ----------
inner_w = plate_w - 2 * corner_r;   // width of the straight central strip
// (inner_l = plate_l - 2 * corner_r would be the straight strip along X,
//  but the cut is a full circle, so it overruns the end strips.)

// ---------- Model ----------
difference() {
    // Plate body
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Rounded corners, cut through the full thickness
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx > 0 ? plate_l / 2 - corner_r : -plate_l / 2,
                   sy > 0 ? plate_w / 2 - corner_r : -plate_w / 2,
                   0])
            cylinder(r = corner_r, h = plate_t + 2 * eps, $fn = 64);

    // Cable-tie hole
    translate([tie_x, tie_y, -eps])
        cylinder(d = tie_hole, h = plate_t + 2 * eps, $fn = 64);
}
