// Spacer washers - a row of identical flat ring spacers that print together.
// Each washer is a separate part and must not touch its neighbours.
// Print orientation: flat on the bed, z = 0 upward.

// ---------------- Parameters ----------------
washer_count   = 4;    // number of washers in the row
washer_d       = 30;   // outer diameter of a washer (mm)
washer_bore    = 10.5; // diameter of the central hole (mm)
washer_t       = 2;    // thickness of a washer (mm)
washer_gap     = 8;    // centre-to-centre spacing between washers (mm)
eps            = 0.5;  // cutter overshoot past faces (mm)
$fn            = 128;  // curve resolution

// Derived: row length and first washer X position (row centred on origin)
row_length   = (washer_count - 1) * washer_gap;
first_x      = -row_length / 2;

// ---------------- Model ----------------
difference() {
    // Stack of washers, each centred on y = 0 and spaced along X
    for (i = [0 : washer_count - 1]) {
        translate([first_x + i * washer_gap, 0, 0])
            cylinder(d = washer_d, h = washer_t);
    }

    // Matching stack of holes, extended past top and bottom faces
    for (i = [0 : washer_count - 1]) {
        translate([first_x + i * washer_gap, 0, -eps])
            cylinder(d = washer_bore, h = washer_t + 2 * eps);
    }
}
