washer_od    = 16;    // outer diameter (mm)
washer_id    = 8.5;   // hole diameter (mm)
washer_t     = 2;     // thickness (mm)
washer_count = 4;     // number of washers
gap          = 10;    // gap between neighbouring washers (mm)
eps          = 0.5;   // cut overshoot past faces (mm)
$fn          = 96;    // circle resolution

// ---- Derived ----
pitch   = washer_od + gap;               // centre-to-centre spacing
x_start = -(washer_count - 1) * pitch / 2; // centres the row on origin

// ---- Modules ----
module washer() {
    difference() {
        cylinder(d = washer_od, h = washer_t);
        translate([0, 0, -eps])
            cylinder(d = washer_id, h = washer_t + 2 * eps);
    }
}

// ---- Build ----
for (i = [0 : washer_count - 1])
    translate([x_start + i * pitch, 0, 0])
        washer();
