// Cross-shaped bottle stabiliser plate
// Print orientation: flat on bed, builds upward in +Z

// ---------- Parameters ----------
plate_t      = 3;     // plate thickness (Z)
arm_len      = 70;    // overall length of each bar (X and Y)
arm_w        = 15;    // width of each bar
hole_d       = 5.5;   // through-hole diameter (centre and arm ends)
end_hole_r   = 27.5;  // distance of arm-end holes from origin
eps          = 0.5;   // cutter overshoot past faces
$fn          = 96;    // curve resolution

// ---------- Model ----------
difference() {
    // Plus-shaped plate
    union() {
        translate([-arm_len/2, -arm_w/2, 0])
            cube([arm_len, arm_w, plate_t]);
        translate([-arm_w/2, -arm_len/2, 0])
            cube([arm_w, arm_len, plate_t]);
    }

    // Centre hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2*eps);

    // Arm-end holes (+X, +Y, -X, -Y)
    for (a = [0, 90, 180, 270])
        rotate([0, 0, a])
            translate([end_hole_r, 0, -eps])
                cylinder(d = hole_d, h = plate_t + 2*eps);
}
