// Display base with bevelled top edges
// Print orientation: flat on XY plane, top face at z = 15

// ---- Dimensions (mm) ----
block_x      = 80;    // base length in X
block_y      = 60;    // base width in Y
block_h      = 15;    // total height
chamfer_w    = 4;     // chamfer width (45 deg)
chamfer_h    = block_h - chamfer_w; // vertical side height (11)
top_x        = block_x - 2 * chamfer_w; // top face length (72)
top_y        = block_y - 2 * chamfer_w; // top face width (52)
eps          = 0.5;   // cutter overshoot past top face

$fn = 64;

difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // 45-degree chamfers along all four top edges
    // (cylinders along X or Y whose axes lie on the top edge)
    for (sx = [-1, 1], sy = [-1, 1]) {
        rotate([0, 0, sx * 90])
            translate([0, -top_y/2 - eps, chamfer_h])
                cylinder(d = chamfer_w * 2, h = eps + 0.01);
        rotate([0, 0, sy * 90])
