ring_bottom_z = ring_top_z - ring_thickness; // = 46
leg_circle_r = leg_circle_d / 2;

// ---------- Model ----------
union() {
    // Flat ring (annulus)
    difference() {
        cylinder(d = ring_outer_d, h = ring_thickness, $fn = 128);
        translate([0, 0, ring_bottom_z])
            cylinder(d = ring_inner_d, h = ring_thickness + 0.01, $fn = 128);
    }

    // Legs, placed on the circle, first on +X
    for (i = [0 : leg_count - 1]) {
        rotate([0, 0, leg_angle * i])
            translate([leg_circle_r, 0, 0])
                cylinder(d = leg_d,
                         h = ring_bottom_z - overlap + 0.01, // into the ring
                         $fn = 64);
    }
}
