// Set of 5 identical spacer washers, printed flat in a single row along X
// Units: mm

// ---- Washer dimensions ----
washer_od    = 30;    // outer diameter
washer_id    = 8.5;   // hole diameter
washer_t     = 3;     // thickness (Z)

// ---- Layout ----
washer_count = 5;     // number of washers
washer_gap   = 8;     // edge-to-edge gap between neighbouring washers

// ---- Derived ----
pitch        = washer_od + washer_gap;              // centre-to-centre spacing
row_offset   = -(washer_count - 1) * pitch / 2;     // centres the row on origin

// ---- Modelling ----
cut_extra    = 0.5;   // cutter overshoot past faces
$fn          = 128;   // curve resolution

module washer() {
    difference() {
        cylinder(d = washer_od, h = washer_t);
        translate([0, 0, -cut_extra])
            cylinder(d = washer_id, h = washer_t + 2 * cut_extra);
    }
}

for (i = [0 : washer_count - 1])
    translate([row_offset + i * pitch, 0, 0])
        washer();
