row_length = (washer_count - 1) * gap;

// ---------------- Model ----------------
difference() {
    // Solid disc for each washer
    for (i = [0 : washer_count - 1]) {
        translate([-row_length / 2 + i * gap, 0, 0]) {
            cylinder(d = outer_d, h = thickness);
        }
    }

    // Central hole through each washer
    for (i = [0 : washer_count - 1]) {
        translate([-row_length / 2 + i * gap, 0, -eps]) {
            cylinder(d = hole_d, h = thickness + 2 * eps);
        }
    }
}
