// Set of 3 identical spacer washers, printed together in a row along X
// Units: mm

$fn = 96;

// --- Washer dimensions ---
washer_od    = 16;    // outer diameter
washer_id    = 8.5;   // hole diameter
washer_t     = 1.5;   // thickness

// --- Layout ---
washer_count = 3;     // number of washers
washer_gap   = 10;    // edge-to-edge gap between neighbouring washers

// --- Derived ---
pitch      = washer_od + washer_gap;            // centre-to-centre spacing
row_offset = (washer_count - 1) * pitch / 2;    // shift to centre row on origin
eps        = 0.5;                               // cutter overshoot

module washer() {
    difference() {
        cylinder(d = washer_od, h = washer_t);
        translate([0, 0, -eps])
            cylinder(d = washer_id, h = washer_t + 2 * eps);
    }
}

for (i = [0 : washer_count - 1])
    translate([i * pitch - row_offset, 0, 0])
        washer();
