// Glass stirring rod rest - block with V-shaped grooves along Y
// Print orientation: base on bed (z = 0), grooves open upward

// ---------------- Parameters ----------------
block_len   = 105;   // block length along X (mm)
block_wid   = 30;    // block width along Y (mm)
block_ht    = 18;    // block height along Z (mm)

groove_n     = 6;    // number of V-grooves
groove_pitch = 15;   // centre-to-centre spacing along X (mm)
groove_wt    = 10;   // groove width at top surface (mm)
groove_d     = 5;    // groove depth from top surface (mm)

eps          = 0.5;  // overcut past faces to avoid coplanar faces (mm)

$fn = 96;

// ---------------- Derived ----------------
// For a 90-degree V, the two faces are at 45 degrees.
// Width at depth d below the top = groove_wt - 2*d
// (check: at d = groove_d = 5, width = 10 - 10 = 0)
function groove_w_at_depth(d) = groove_wt - 2 * d;

// X position of groove i, centred on the block
function groove_x(i) = (i - (groove_n - 1) / 2) * groove_pitch;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves cut through the full width along Y
    for (i = [0 : groove_n - 1]) {
        translate([groove_x(i), -block_wid / 2 - eps, block_ht - groove_d])
            linear_extrude(height = block_wid + 2 * eps)
                polygon([[-groove_wt / 2, -groove_wt / 2], [0, groove_wt / 2], [groove_wt / 2, -groove_wt / 2]]);
    }
}
