// Glass stirring rod rest - rectangular block with V-grooves
// Units: mm

// ---------- Block ----------
block_len   = 105;   // length along X
block_wid   = 30;    // width along Y
block_ht    = 18;    // height along Z

// ---------- Grooves ----------
groove_count = 6;    // number of V-grooves
groove_pitch = 15;   // centre-to-centre spacing along X
groove_top_w = 10;   // groove width at top surface
groove_depth = 5;    // groove depth (90-degree V: depth = top_w/2)
overcut      = 1;    // extension past cut faces to avoid coplanar faces

$fn = 64;

// Half-width grows 1:1 with height for a 90-degree V
module v_groove() {
    hw_top = groove_top_w / 2 + overcut;   // half-width at overcut height
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * overcut, center = true)
            polygon([
                [0, block_ht - groove_depth],          // apex
                [ hw_top, block_ht + overcut],         // upper right
                [-hw_top, block_ht + overcut]          // upper left
            ]);
}

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves centred along X
    for (i = [0 : groove_count - 1])
        translate([(i - (groove_count - 1) / 2) * groove_pitch, 0, 0])
            v_groove();
}
