// Keyhole wall plate - hangs on a screw head
// Print orientation: flat on bed, z = 0 up to plate thickness

// ---------- Plate ----------
plate_len   = 60;   // plate length along X (mm)
plate_wid   = 35;   // plate width along Y (mm)
plate_thk   = 3;    // plate thickness along Z (mm)

// ---------- Keyhole ----------
head_d      = 10;   // round entry hole diameter (screw head passes through)
head_x      = 0;    // centre of entry hole, X
head_y      = 0;    // centre of entry hole, Y
slot_w      = 5;    // slot width (screw shank rides in this)
slot_end_x  = 10;   // X of the rounded slot end's centre
slot_end_y  = 0;    // Y of the rounded slot end's centre

// ---------- Misc ----------
cut_ext     = 0.5;  // extra length for cutters past faces
$fn         = 96;   // circle resolution

module keyhole_2d() {
    union() {
        // round entry hole
        translate([head_x, head_y]) circle(d = head_d);
        // straight slot with rounded end (hull of two circles)
        hull() {
            translate([head_x, head_y])         circle(d = slot_w);
            translate([slot_end_x, slot_end_y]) circle(d = slot_w);
        }
    }
}

difference() {
    // plate centred on origin in XY, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // keyhole cut through full thickness
    translate([0, 0, -cut_ext])
        linear_extrude(height = plate_thk + 2 * cut_ext)
            keyhole_2d();
}
