// Stepped riser - solid staircase of 3 equal steps, print orientation: base on bed,
// profile climbs in +X direction. NOVEL general part.
//

$fn = 64;

// ---- Dimensions (mm) ----
step_count   = 3;     // number of steps
step_length  = 15;    // X length of each step
step_height  = 8;     // height gain of each step over the previous
top_height   = 24;    // height of the top step (check: step_height * step_count)
end_x        = 45;    // X position of the top of the last step (check: step_length * step_count)
extrude_y    = 20;    // Y thickness of the extrusion (y = 0 to y = 20)
overcut      = 0.5;   // extra length so cutters pass beyond the end faces

// Derived
first_h = step_height;                  // first step height (8 mm)
x0 = 0;                                 // X start of first step

// Each step is a block [x0 + i*L : x0 + (i+1)*L] x [0 : extrude_y] x [h_i : h_i + L]
// with a small overlap in X and Z so the union fuses cleanly.
for (i = [0 : step_count - 1]) {
    h_i = first_h + i * step_height;
    union() {
        translate([x0 + i * step_length - overcut, 0, h_i])
            cube([step_length + 2 * overcut, extrude_y, step_height]);
        // connector block under the step, fuses it to the bed and to the previous step
        translate([x0 + i * step_length - overcut, 0, 0])
            cube([step_length + 2 * overcut, extrude_y, h_i + 0.01]);
    }
}
