module display_base() {
    union() {
        // Vertical-sided lower block, sharp bottom edges
        translate([-base_x / 2, -base_y / 2, 0])
            cube([base_x, base_y, side_h]);

        // Chamfered top section: hull between full footprint at z = side_h
        // and reduced top face at z = base_h
        hull() {
            translate([-base_x / 2, -base_y / 2, side_h - eps])
                cube([base_x, base_y, eps]);
            translate([-top_x / 2, -top_y / 2, base_h - eps])
                cube([top_x, top_y, eps]);
        }
    }
}

