ring_inner_d      = 54;   // ring inner (bore) diameter
ring_thickness    = 4;    // ring thickness (Z)
ring_top_z        = 50;   // ring top face height
leg_d             = 6;    // leg diameter
leg_count         = 3;    // number of legs
leg_circle_d      = 62;   // diameter of circle the leg axes lie on
leg_start_angle   = 0;    // first leg on +X axis (degrees)
overlap           = 0.5;  // leg embed depth into ring for a clean union
$fn               = 96;   // curve resolution

// ---------- Derived ----------
leg_bottom_z = ring_top_z - ring_thickness - overlap;  // leg start (z = 45.5)

// ---------- Model ----------
union() {
    // Flat annulus ring
    difference() {
        cylinder(d = ring_outer_d, h = ring_thickness, $fn = 128);
        translate([0, 0, ring_top_z - ring_thickness])
            cylinder(d = ring_inner_d, h = ring_thickness + 0.01, $fn = 128);
    }

    // Three legs, axes on the specified circle, 120 deg apart
    for (i = [0 : leg_count - 1]) {
        rotate([0, 0, leg_start_angle + i * 360 / leg_count])
            translate([leg_circle_d / 2, 0, leg_bottom_z])
                cylinder(d = leg_d, h = ring_top_z + 1, $fn = 64);
    }
}
