plate_thk      = 6;    // base plate thickness (Z)

rail_bot_w     = 10;   // rail width at the plate interface (z = 6)
rail_top_w     = 14;   // rail width at its top face (z = 12)
rail_h         = rail_top_w - rail_bot_w; // rail height (6 mm)

eps            = 0.5;  // overcut so cutting shapes pass beyond faces
$fn            = 96;   // curve resolution

// ---------- Derived ----------
rail_top_z     = plate_thk + rail_h;  // top face of rail (12)
slope          = (rail_top_w - rail_bot_w) / rail_h;  // 0.6667 mm/mm

// ---------- Model ----------
union() {
    // Base plate, centred in X and Y
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail, centred on y = 0
    translate([-plate_len/2, -rail_bot_w/2, plate_thk])
        linear_extrude(height = rail_h)
            polygon([[-rail_bot_w/2, 0], [rail_bot_w/2, 0],
                     [rail_top_w/2, rail_h], [-rail_top_w/2, rail_h]]);
}

// ---------- Inspect ----------
difference() {
    // Duplicate of the union, with the rail overcut into the plate.
    // This removes any coplanar faces between the two parts.
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    translate([-plate_len/2, -rail_bot_w/2 - eps, plate_thk])
        linear_extrude(height = rail_h + 2*eps)
            polygon([[-rail_bot_w/2, 0], [rail_bot_w/2, 0],
                     [rail_top_w/2, rail_h], [-rail_top_w/2, rail_h]]);
}
