boss_d      = 30;    // boss diameter
boss_top_z  = 31;    // top of boss (boss runs z = 6 to 31)
rod_hole_d  = 10.5;  // rod hole diameter
floor_t     = 2;     // closed floor thickness under the rod hole
overlap     = 0.5;   // overlap/overcut to avoid coplanar faces

$fn = 128;

// ---------- Model ----------
difference() {
    union() {
        // Base disc
        cylinder(d = disc_d, h = disc_h);
        // Boss (starts slightly inside the disc for a clean union)
        translate([0, 0, disc_h - overlap])
            cylinder(d = boss_d, h = boss_top_z - disc_h + overlap);
    }
    // Rod hole: from z = floor_t up through the top of the boss
    translate([0, 0, floor_t])
        cylinder(d = rod_hole_d, h = boss_top_z - floor_t + overlap);
}
