// Glass stirring rod rest
// Print orientation: flat on bed, grooves facing up

// ---- Block dimensions ----
block_len   = 104;   // length along X
block_wid   = 40;    // width along Y
block_ht    = 18;    // height along Z

// ---- Groove parameters ----
