groove_pitch = 20;   // centre-to-centre spacing along X
groove_wt    = 10;   // groove width at top surface (mm)
groove_d    = 5;     // groove depth from top surface (mm)

// ---- Derived ----
overcut = 0.5;       // extension of cutters past top face
x0 = -(groove_n - 1) * groove_pitch / 2;  // first groove centre X

$fn = 96;

difference() {
    // Main block
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves (90-degree profile: two 45-degree planar faces)
    for (i = [0 : groove_n - 1]) {
        x = x0 + i * groove_pitch;
        // cutter block, wider at top to keep a true V through the full depth
        w_top = groove_wt + 2 * overcut;
        w_bot = groove_wt * (block_ht - groove_d) / block_ht;
        translate([x - w_top/2, -block_wid/2 - overcut, block_ht - groove_d])
            cube([w_top, block_wid + 2 * overcut, groove_d + overcut]);
    }
}
