// Half-width of the cutter at its top (extended above the surface,
// keeping the 90-degree V so the profile at z = block_ht is exact)
cutter_half_w = groove_top_w / 2 + cut_over;

module v_groove_cutter() {
    // V profile in the XZ plane, extruded along Y through the full width
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * cut_over, center = true)
            polygon(points = [
                [-cutter_half_w, block_ht + cut_over],
                [ cutter_half_w, block_ht + cut_over],
                [ 0,             block_ht - groove_depth]
            ]);
}

difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // Row of V-grooves, centred along X
    for (i = [0 : groove_count - 1])
        translate([(i - (groove_count - 1) / 2) * groove_pitch, 0, 0])
            v_groove_cutter();
}
