// ---------- Model ----------
difference() {
    // Plus-shaped plate
    union() {
        translate([-arm_len/2, -arm_w/2, 0])
            cube([arm_len, arm_w, plate_t]);   // bar along X
        translate([-arm_w/2, -arm_len/2, 0])
            cube([arm_w, arm_len, plate_t]);   // bar along Y
    }

    // Centre hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_t + 2*cut_extra);

    // Arm-end holes
    for (a = [0, 90, 180, 270])
        rotate([0, 0, a])
            translate([hole_offset, 0, -cut_extra])
                cylinder(d = hole_d, h = plate_t + 2*cut_extra);
}
