    // Cut out the empty space under each step, from y = 0 to y = extrusion
    for (i = [0 : step_count - 1]) {
        translate([x0 + i * step_length - eps, 0, first_height + i * step_height])
            cube([step_length + 2 * eps, extrusion + 2 * eps, step_height]);
    }
}
