    // Build the plate with rounded corners using a superellipse outline
    hull() {
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx * (plate_l / 2 - corner_r),
                       sy * (plate_w / 2 - corner_r),
                       0])
                cylinder(r = corner_r, h = plate_t + 2 * eps, $fn = 96);
