        linear_extrude(height = plate_t + 2 * eps)
            circle(d = plate_l - 2 * corner_r, h = plate_w - 2 * corner_r, $fn = 96);
}

module tie_hole() {
    translate([tie_x, tie_y, -eps])
        cylinder(d = tie_hole, h = plate_t + 2 * eps, $fn = 64);
}

// ---------- Part ----------
difference() {
    rounded_plate();
    tie_hole();
}
