```openscad
// Door-stop wedge with a vertical through-slot
// Uses the coordinates given: wedge spans x 0..80, y 0..35, z 0..30 (not centred)

$fn = 64;

// ---- Wedge dimensions ----
wedge_length = 80;    // X length of the wedge base
wedge_width  = 35;    // Y width (extrusion depth)
wedge_height = 30;    // Z height at x = 0

// ---- Slot dimensions ----
slot_width    = 6;    // slot size along Y
slot_length   = 40;   // slot size along X
slot_center_x = 40;   // slot centre in X
slot_center_y = 17.5; // slot centre in Y

// ---- Cutting overshoot ----
eps = 1;              // extension of cutters past the faces they cut

module wedge_body() {
    // Right triangle in XZ: (0,0), (80,0), (0,30), extruded y = 0..35.
    // rotate([90,0,0]) maps the polygon's Y to Z and extrudes toward -Y,
    // so translate by +width to place it at y = 0..35.
    translate([0, wedge_width, 0])
        rotate([90, 0, 0])
            linear_extrude(height = wedge_width)
                polygon(points = [
                    [0, 0],
                    [wedge_length, 0],
                    [0, wedge_height]
                ]);
}

module slot_cutter() {
    translate([slot_center_x - slot_length / 2,
               slot_center_y - slot_width / 2,
               -eps])
        cube([slot_length, slot_width, wedge_height + 2 * eps]);
}

difference() {
    wedge_body();
    slot_cutter();
}
```

