    // rotate([90,0,0]) maps polygon Y -> Z and extrusion Z -> -Y,
    // so translate by +wedge_width in Y to span y = 0..wedge_width.
    translate([0, wedge_width, 0])
        rotate([90, 0, 0])
            linear_extrude(height = wedge_width)
                polygon(points = [
                    [0, 0],
                    [wedge_length, 0],
                    [0, wedge_height]
                ]);

    // Vertical rectangular slot running through the whole wedge
    translate([slot_center_x - slot_length / 2,
               slot_center_y - slot_width / 2,
               -eps])
        cube([slot_length, slot_width, wedge_height + 2 * eps]);
