// Spacer washers - a row of identical flat ring washers that print together.
// Each washer is a separate part and must not touch its neighbours.
// Print orientation: flat on the bed, z = 0 upward.

// ---------------- Parameters ----------------
washer_count   = 5;    // number of washers in the row
washer_od      = 24;   // outer diameter of each washer (mm)
washer_id      = 10.5; // inner diameter of each washer (mm)
washer_t       = 2;    // thickness of each washer (mm)
washer_gap     = 10;   // centre-to-centre spacing between washers (mm)
eps            = 0.5;  // cutter overshoot past faces (mm)

$fn = 128;             // smoothness of curved shapes

// ---------------- Model ----------------
difference() {
    // Solid disc from which the central hole is cut
    cylinder(d = washer_od, h = washer_t);

    // Through-hole, extended past both faces to avoid coplanar surfaces
    translate([0, 0, -eps])
        cylinder(d = washer_id, h = washer_t + 2 * eps);
}

// ---------------- Layout ----------------
// Place the washers in a single row along X, centred on y = 0,
// and centre the entire row on the origin.
for (i = [0 : washer_count - 1]) {
    x = (i - (washer_count - 1) / 2) * washer_gap;
    translate([x, 0, 0])
        // Duplicate the washer with $fn preserved so the hole stays round
        cylinder(d = washer_od, h = washer_t, $fn = 128);
}
