// Glass stirring rod rest - block with V-shaped grooves along Y
// Print orientation: flat on bed, grooves facing up

// ---------- Block ----------
block_len   = 100;   // block length along X (mm)
block_wid   = 50;    // block width along Y (mm)
block_ht    = 12;    // block height along Z (mm)

// ---------- Grooves ----------
groove_n     = 5;    // number of V grooves
groove_pitch = 20;   // centre-to-centre spacing along X (mm)
groove_wt    = 10;   // groove width at top surface (mm)
groove_dep   = 5;    // groove depth from top surface (mm)

// ---------- Derived ----------
overcut = 0.5;       // extra length so cutters pass through faces (mm)
x0      = -(groove_n - 1) * groove_pitch / 2;  // X of first groove centre
alpha   = 45;        // V groove wall angle from horizontal (deg)

// Check: 5 * 10 + 2 * 5 = 70 mm top width of grooves < block width 50 mm
// (grooves overlap near the Y extremes, which is fine)

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-shaped grooves, running full width along Y
    for (i = [0 : groove_n - 1]) {
        translate([x0 + i * groove_pitch - groove_wt / 2, 0,
                   block_ht - groove_dep])
            linear_extrude(height = block_wid + 2 * overcut)
                polygon([[-groove_wt / 2, 0], [groove_wt / 2, 0],
                         [0, -groove_wt / 2 / tan(alpha)]]);
    }
}
