// Glass stirring rod rest - rectangular block with V-grooves across the top
// Print orientation: flat bottom on the bed (z = 0), grooves facing up

// ---------- Block dimensions ----------
block_length = 100;   // X length of block (mm)
block_width  = 50;    // Y width of block (mm)
block_height = 12;    // Z height of block (mm)

// ---------- Groove parameters ----------
groove_count    = 5;    // number of V-grooves
groove_pitch    = 20;   // centre-to-centre spacing along X (mm)
groove_top_w    = 10;   // groove width at the top surface (mm)
groove_depth    = 5;    // groove depth from the top surface (mm), 90-degree V
cut_overlap     = 1;    // extra cutter extension past faces (mm)

$fn = 64;

// Half-width grows 1:1 with height for a 90-degree V
half_top = groove_top_w / 2;               // 5 mm
half_ext = half_top + cut_overlap;         // half-width at top + overlap

// V-groove cutter: profile drawn in XZ, extruded along Y
module v_groove() {
    rotate([90, 0, 0])
        linear_extrude(height = block_width + 2 * cut_overlap, center = true)
            polygon(points = [
                [0,         block_height - groove_depth],   // apex of V
                [ half_ext, block_height + cut_overlap],    // top right (above surface)
                [-half_ext, block_height + cut_overlap]     // top left (above surface)
            ]);
}

difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_length / 2, -block_width / 2, 0])
        cube([block_length, block_width, block_height]);

    // Grooves centred along X
    for (i = [0 : groove_count - 1])
        translate([(i - (groove_count - 1) / 2) * groove_pitch, 0, 0])
            v_groove();
}
