```openscad
// Stepped riser - a solid 4-step staircase, extruded along Y, for setting samples at different heights.
// Print orientation: base on the bed (z = 0), steps climbing in +X.
// Units: mm

$fn = 64;

// ---- Step parameters ----
step_count   = 4;    // number of steps
step_length  = 10;   // X length of each step (also the height gain per step)
first_height = 10;   // height of the first step (z at x = 0 to x = 10)
extrude_y    = 30;   // length along Y (from y = 0 to y = 30)

// ---- Derived ----
top_height = first_height + step_count * step_length;  // 50 mm at the top step end (x = 40)
x_start    = 0;                                        // first step starts at x = 0
x_end      = x_start + step_count * step_length;       // last step ends at x = 40

// ---- Model ----
difference() {
    // Solid block covering the full X range, with a small cutout at the top end so the
    // last step does not run into the next one (keeps the profile clean).
    translate([x_start, 0, 0])
        cube([x_end + 1, extrude_y, top_height]);

    // Cutout at the very top end, extending past the faces to avoid coplanar surfaces.
    translate([x_end - step_length, 0, top_height - step_length])
        cube([step_length + 2, extrude_y + 2, step_length + 2]);
}
```

```openscad
// Stepped riser: 4-step solid staircase climbing in +X
// Placed at the user-specified coordinates: x = 0..40, y = 0..30, z = 0..40

// ---- Parameters ----
num_steps   = 4;    // number of steps
step_length = 10;   // length of each step along X (mm)
step_rise   = 10;   // height increase per step (mm)
depth       = 30;   // extrusion depth along Y (mm)

total_length = num_steps * step_length; // overall X length (40 mm)

// ---- Model ----
// Each block starts at its step's X position and runs to the far end,
// so the blocks overlap instead of only touching at shared faces.
union() {
    for (i = [0 : num_steps - 1]) {
        translate([i * step_length, 0, 0])
            cube([total_length - i * step_length,  // run to the end (overlapping)
                  depth,
                  (i + 1) * step_rise]);            // step height: 10, 20, 30, 40
    }
}
```

