extrude_w    = 30;    // Y-width of the staircase (mm)
eps          = 0.5;   // cutter overshoot past top faces (mm)

// Derived: top height of the last step
top_height = step_height * step_count;   // 32 mm

// ---------- Model ----------
difference() {
    // Solid block that covers the full staircase footprint
    translate([0, 0, 0])
        cube([step_length * step_count, extrude_w, top_height]);

    // Cut out the "undercut" of each step so it stands on the step below
    for (i = [0 : step_count - 1]) {
        x0 = i * step_length;
        translate([x0, 0, i * step_height + eps])
            cube([step_length, extrude_w, step_height - 2 * eps]);
    }
}
