cor_y = plate_w / 2 - r;

difference() {
    // Plate body
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Four corner fillets, cut from the top and bottom faces
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx * cor_x, sy * cor_y, -eps])
            cylinder(r = r, h = plate_t + 2 * eps);

    // Cable tie hole through the full thickness
    translate([tie_x, tie_y, -eps])
        cylinder(d = tie_d, h = plate_t + 2 * eps);
}
