plate_width    = 20;    // overall width along Y
plate_thick    = 3;     // plate thickness along Z
corner_radius  = 5;     // corner radius seen from above

hole_diameter  = 4;     // cable-tie hole diameter
hole_x         = -27;   // hole centre X position
hole_y         = 0;     // hole centre Y position

cut_extra      = 0.5;   // extra length so cutters pass through faces

$fn = 64;               // circle resolution

// ---------- Rounded-rectangle outline ----------
module rounded_rect_2d(l, w, r) {
    hull() {
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx * (l / 2 - r), sy * (w / 2 - r)])
                circle(r = r, $fn = 64);
    }
}

// ---------- Part ----------
difference() {
    // Plate body, resting on z = 0
    linear_extrude(height = plate_thick)
        rounded_rect_2d(plate_length, plate_width, corner_radius);

    // Cable-tie hole, extends past top and bottom faces
    translate([hole_x, hole_y, -cut_extra])
        cylinder(d = hole_diameter, h = plate_thick + 2 * cut_extra, $fn = 64);
}
