// Flask support ring with three round legs
// Print orientation: ring top face at z = 40, legs run down to z = 0

// ---------- Parameters ----------
ring_outer_d      = 90;    // ring outer diameter
ring_inner_d      = 66;    // ring inner (bore) diameter
ring_thickness    = 6;     // ring thickness (Z)
ring_top_z        = 40;    // ring top face height
leg_d             = 8;     // leg diameter
leg_count         = 3;     // number of legs
leg_circle_d      = 78;    // diameter of circle the leg axes lie on
leg_angle         = 120;   // angle between legs (degrees)
leg_first_on_x    = true;  // first leg on +X axis
cut_overlap       = 0.5;   // extra length of cutters past faces
$fn               = 96;    // curve resolution

// ---------- Derived ----------
leg_bottom_z = 0;                        // legs end at the bed
ring_bottom_z = ring_top_z - ring_thickness;  // ring bottom face (34)
leg_cylinder_h = ring_bottom_z - leg_bottom_z + cut_overlap;  // 40.5

// ---------- Model ----------
union() {
    // Flat annulus ring
    difference() {
        cylinder(d = ring_outer_d, h = ring_thickness, $fn = 128);
        translate([0, 0, ring_bottom_z])
            cylinder(d = ring_inner_d, h = ring_thickness + 1, $fn = 128);
    }

    // Three legs, axes on the specified circle
    for (i = [0 : leg_count - 1]) {
        a = leg_angle * i;
        translate([leg_circle_d / 2 * cos(a),
                   leg_circle_d / 2 * sin(a),
                   leg_bottom_z])
            cylinder(d = leg_d, h = leg_cylinder_h, $fn = 64);
    }
}
