```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate on the bed, rail pointing up (+Z)

// ---------- Parameters ----------
plate_len      = 60;   // base plate length (X)
plate_wid      = 40;   // base plate width (Y)
plate_thk      = 5;    // base plate thickness (Z)

rail_bot_w     = 10;   // rail width at the plate interface (z = 5)
rail_top_w     = 16;   // rail width at its top face (z = 13)
rail_top_z     = 13;   // rail top face height (Z)

overcut        = 0.5;  // extra length so cutters pass through end faces
$fn            = 96;   // curve resolution

// ---------- Derived ----------
rail_h = rail_top_z - plate_thk;              // rail height above plate (8)
x0     = -plate_len/2 + overcut;              // lower end X
x1     = plate_len/2 - overcut;               // upper end X

// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail: two slanted walls between the end widths, capped at the top
    difference() {
        hull() {
            for (x = [x0, x1])
                translate([x, 0, plate_thk])
                    cylinder(h = rail_h + 0.01, r = rail_bot_w/2);
        }
        // Cut away everything above the top face, leaving a flat cap
        translate([x0, -rail_top_w/2 - 0.01, rail_top_z])
            cube([x1 - x0, rail_top_w + 0.02, overcut]);
    }
}
