    // rotate([90,0,90]) maps polygon x->Y, y->Z, extrude z->X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_bot_w/2, plate_thk - overlap], // overlap into plate
                [ rail_bot_w/2, plate_thk - overlap],
                [ rail_bot_w/2, plate_thk],           // base of flare
                [ rail_top_w/2, rail_top_z],          // top outer edge
                [-rail_top_w/2, rail_top_z],
                [-rail_bot_w/2, plate_thk]
            ]);
}

union() {
    base_plate();
    dovetail_rail();
}
