rail_top_z  = plate_thk + rail_h;   // top of rail (10)
slope       = (rail_top_w - rail_bot_w) / (2 * rail_h);  // 0.33 mm per mm Z

// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail
    translate([-plate_len/2, 0, plate_thk])
        linear_extrude(height = rail_h + eps)
            polygon([[-rail_bot_w/2, 0], [rail_bot_w/2, 0],
                     [rail_top_w/2, rail_h], [-rail_top_w/2, rail_h]]);
}
