// Weighted base for lab stand rod
// Print orientation: flat disc on bed, boss pointing up

// ---------- Parameters ----------
disc_d        = 100;   // disc diameter
disc_t        = 10;    // disc thickness (z = 0 to 10)
boss_d        = 20;    // boss diameter
boss_top_z    = 30;    // top of boss (boss rises z = 10 to 30)
rod_d         = 8.5;   // rod hole diameter
hole_clear    = 0.5;   // extra hole length past faces to avoid coplanar faces
$fn           = 128;   // curve resolution

// Derived
hole_bottom_z = boss_top_z - rod_d - hole_clear; // = 21.0, hole ends 2 mm above bed
boss_h        = boss_top_z - disc_t;             // boss height = 20

// ---------- Model ----------
union() {
    // Base disc
    cylinder(d = disc_d, h = disc_t);

    // Coaxial boss, cut through with rod hole
    difference() {
        translate([0, 0, disc_t])
            cylinder(d = boss_d, h = boss_h);
        translate([0, 0, -hole_clear])
            cylinder(d = rod_d, h = boss_h + 2 * hole_clear); // runs z = 10 to 30.5
    }
}
