    for (i = [0 : groove_n - 1]) {
        translate([-ax + i * groove_pitch, -block_wid / 2 - eps,
                   block_ht - groove_d])
            linear_extrude(height = block_wid + 2 * eps)
                polygon([[-gt / 2, 0], [gt / 2, 0], [0, -gt / 2]]);
