z0 = first_height;            // bed height (first step stands on it)
x_end = x0 + step_count * step_length;  // X position of the top step end (60)

// ---------- Model ----------
difference() {
    // Solid block that covers the full staircase volume
    translate([x0, 0, z0])
        cube([step_count * step_length, extrusion, top_height - z0 + step_height]);

    // Cut out the "undercut" of each step so the profile, viewed from +X,
    // climbs step by step. Each cut extends past the faces it removes.
    for (i = [0 : step_count - 1]) {
        x = x0 + i * step_length;
        z = z0 + i * step_height;
        translate([x, 0, z])
            cube([step_length, extrusion + 1, step_height + 1]);
    }
}
