```openscad
// Stepped riser - solid staircase of 5 equal steps
// Profile in XZ climbs toward +X, extruded along Y from y = 0 to y = 40.
// Positioned per the user's coordinates (x 0..60, y 0..40), resting on z = 0.

n_steps     = 5;    // number of steps
step_len    = 12;   // length of each step in X (mm)
step_rise   = 8;    // height increase per step (mm)
riser_depth = 40;   // extrusion depth along Y (mm)

total_len    = n_steps * step_len;   // 60 mm
total_height = n_steps * step_rise;  // 40 mm

// Staircase profile in the (X, Z) plane, counter-clockwise
profile_pts = concat(
    [[0, 0], [total_len, 0]],
    // walk back from the top step down to the first step
    [ for (i = [n_steps - 1 : -1 : 0]) each [
        [(i + 1) * step_len, (i + 1) * step_rise],
        [ i      * step_len, (i + 1) * step_rise]
    ] ]
);

// rotate([90,0,0]) maps profile Y to world Z and extrudes toward -Y,
// so shift by riser_depth to occupy y = 0 .. 40
translate([0, riser_depth, 0])
    rotate([90, 0, 0])
        linear_extrude(height = riser_depth)
            polygon(points = profile_pts);
```

