    cylinder(d = disc_d, h = disc_t);

    // Coaxial boss
    translate([0, 0, disc_t])
        cylinder(d = boss_d, h = boss_h);

    // Through hole, but with floor under it
    translate([0, 0, disc_t + hole_clear])
        difference() {
            cylinder(d = rod_d, h = boss_h + hole_clear);
            // keep the floor: intersect with z <= floor_thick
            translate([0, 0, -floor_thick])
                cylinder(d = rod_d + 0.01, h = floor_thick + hole_clear + 0.01);
        }
}
