// Spacer washers - a row of identical flat ring washers that print together.
// Each washer is a separate part and must not touch its neighbours.
// Print orientation: flat on the bed, z = 0 upward.

// ---------------- Parameters ----------------
washer_count   = 5;    // number of washers in the row
outer_d        = 30;   // outer diameter of each washer (mm)
hole_d         = 6.5;  // diameter of the central hole (mm)
thickness      = 3;    // washer thickness (mm)
gap            = 8;    // centre-to-centre spacing between washers (mm)
eps            = 0.5;  // cutter overshoot past faces (mm)
$fn            = 128;  // curve resolution

// Derived: distance from the row centre to the first washer centre
row_offset = (washer_count - 1) * gap / 2;

// ---------------- Model ----------------
difference() {
    union() {
        for (i = [0 : washer_count - 1]) {
            translate([row_offset + i * gap, 0, 0])
                cylinder(d = outer_d, h = thickness);
        }
    }

    // Through-holes, cut past both faces so no faces are coplanar
    for (i = [0 : washer_count - 1]) {
        translate([row_offset + i * gap, 0, -eps])
            cylinder(d = hole_d, h = thickness + 2 * eps);
    }
}
