        [ groove_half + eps, block_h + eps],        // right flank, above top
        [-(groove_half + eps), block_h + eps]       // left flank, above top
    ]);
}

module groove_cutter() {
    // Extrude profile along Y, running past both side faces
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * eps, center = true)
            v_groove_profile();
}

difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // V-grooves across the full width
    for (i = [0 : groove_count - 1])
        translate([first_x + i * groove_pitch, 0, 0])
            groove_cutter();
}
