// Glass stirring rod rest - rectangular block with 3 V-grooves across the top

// ---------- Block dimensions ----------
block_len   = 54;   // block length along X (mm)
block_wid   = 40;   // block width along Y (mm)
block_h     = 18;   // block height along Z (mm)

// ---------- Groove dimensions ----------
groove_count = 3;   // number of V-grooves
groove_pitch = 15;  // centre-to-centre spacing along X (mm)
groove_top_w = 10;  // groove width at top surface (mm)
groove_depth = 5;   // groove depth (mm), 90-degree V (half-width = depth)

// ---------- Cutting overlap ----------
eps = 0.5;          // extension of cutters past faces (mm)

$fn = 64;

// Profile of one V-groove (X horizontal, Y = vertical/Z after rotation)
// Apex at depth; sides at 45 deg, extended eps above the top surface
module groove_profile() {
    polygon(points = [
        [0, -groove_depth],
        [ groove_top_w/2 + eps, eps],
        [-(groove_top_w/2 + eps), eps]
    ]);
}

difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_h]);

    // V-grooves running full width along Y, centred along X
    for (i = [0 : groove_count - 1]) {
        x = (i - (groove_count - 1)/2) * groove_pitch;
        translate([x, 0, block_h])
            rotate([90, 0, 0])
                linear_extrude(height = block_wid + 2*eps, center = true)
                    groove_profile();
    }
}
```

