// Split collet for tube gripping
// Print orientation: standing on bed, slots open at top end

// ---- Dimensions (mm) ----
tube_od      = 16;   // tube outer diameter
tube_bore    = 12;   // tube bore diameter
height       = 20;   // collet height (z = 0 to 20)
slot_width   = 2;    // slot width
slot_depth   = 15;   // slot depth from top end (down to z = 5)
slot_count   = 4;    // number of slots
eps          = 0.5;  // cutter overshoot past faces

$fn = 96;

difference() {
    // Main body: tube wall as solid
    cylinder(h = height, d = tube_od);

    // Bore through the centre
    translate([0, 0, -eps])
        cylinder(h = height + 2 * eps, d = tube_bore);

    // Straight slots along the axis, evenly spaced, first on +X
    for (i = [0 : slot_count - 1])
        rotate([0, 0, i * 360 / slot_count])
            translate([0, 0, height - slot_depth])
                cube([slot_depth + eps, tube_od / 2 + eps, slot_width]);
}
