// Split collet - round tube with axial slots
// Print orientation: standing on bed, z = 0 to z = 20, centred on Z axis

$fn = 96;

// ---- Dimensions (mm) ----
outer_d     = 16;    // tube outer diameter
bore_d      = 12;    // tube bore diameter
tube_h      = 20;    // tube height (z = 0 to 20)

slot_count  = 4;     // number of axial slots
slot_w      = 2;     // slot width
slot_bottom = 5;     // slots run from top down to this z
slot_angle0 = 0;     // first slot centred on +X axis (deg)

eps         = 0.5;   // overcut for clean boolean cuts

// ---- Derived ----
outer_r = outer_d / 2;
bore_r  = bore_d / 2;
slot_len_radial = outer_r - bore_r + 2 * eps;          // radial extent of slot cutter
slot_h          = tube_h - slot_bottom + eps;          // slot height incl. overcut at top

// ---- Model ----
difference() {
    // Tube body
    cylinder(h = tube_h, r = outer_r);

    // Bore (through)
    translate([0, 0, -eps])
        cylinder(h = tube_h + 2 * eps, r = bore_r);

    // Axial slots through the wall
    for (i = [0 : slot_count - 1]) {
        rotate([0, 0, slot_angle0 + i * 360 / slot_count])
            translate([bore_r - eps, -slot_w / 2, slot_bottom])
                cube([slot_len_radial, slot_w, slot_h]);
    }
}
