```openscad
// Cross-shaped stabiliser for a tall bottle
// Print orientation: flat on the bed, z = 0 up to plate_t

// ---------- Parameters ----------
plate_t      = 4;     // plate thickness (Z)
bar_len      = 60;    // length of each arm (X and Y)
bar_w        = 12;    // width of each arm
hole_centre  = 24;    // distance from origin to each arm-end hole centre
hole_d       = 4.5;   // diameter of the two through-holes
eps          = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Model ----------
difference() {
    // Main cross plate
    union() {
        // Horizontal bar (along X)
        translate([-bar_len/2, -bar_w/2, 0])
            cube([bar_len, bar_w, plate_t]);
        // Vertical bar (along Y)
        translate([-bar_w/2, -bar_len/2, 0])
            cube([bar_w, bar_len, plate_t]);
    }

    // Central hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2*eps);

    // Arm-end holes, centred 24 mm from the origin
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx * hole_centre, sy * hole_centre, -eps])
            cylinder(d = hole_d, h = plate_t + 2*eps);
}
```

