// Stepped riser - a solid staircase of 5 equal steps, extruded along Y.
// Print orientation: base on the bed (z = 0), climbing in +X.
// Units: mm

// ---------- Parameters ----------
step_count   = 5;     // number of steps
step_length  = 15;    // X length of each step
