top_height   = 40;    // height of the top step (check: step_count * step_height)
end_x        = 75;    // X position of the top step end (check: step_count * step_length)
extrude_y    = 20;    // Y thickness of the staircase
eps          = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Model ----------
difference() {
    // Solid block covering the full staircase volume
    translate([0, 0, 0])
        cube([end_x, extrude_y, top_height]);

    // Cut out the "tread" of each step, leaving only the risers
    // Steps run from x = 0 to x = end_x, but the last cut would overcut,
    // so we stop at the second-to-last step.
    for (i = [0 : step_count - 2]) {
        x0 = i * step_length;
        x1 = (i + 1) * step_length;
        h  = (i + 1) * step_height;
        translate([x0, 0, h])
            cube([step_length, extrude_y + 2 * eps, eps]);
    }
}
